  simple_capacitor: "C",
  simple_inductor: "L",
  simple_diode: "D",
  simple_led: "D",
  simple_chip: "U",
  simple_transistor: "Q",
  simple_mosfet: "Q",
  simple_fuse: "F",
  simple_switch: "SW",
  simple_push_button: "SW",
  simple_potentiometer: "RV",
  simple_crystal: "Y",
  simple_resonator: "Y",
  simple_pin_header: "J",
  simple_pinout: "J",
