      circuitJson: partitionCircuitJsonBySheet(this.circuitJson, null),
      fileUuid: rootUuid,
      symbolInstancePathPrefix: `/${rootUuid}`,
      emitSheetInstances: true,
      childSheetNodes,
      extraPaperExtentMm: extentMm
