// lib/pcb/stages/InitializePcbStage.ts
import {
  Paper as Paper2,
  PcbLayers,
  PcbLayerDefinition,
  PcbGeneral,
  Setup
} from "kicadts";
var InitializePcbStage = class extends ConverterStage {
  _step() {
    const { kicadPcb, db } = this.ctx;
    if (!kicadPcb) {
      throw new Error("KicadPcb instance not initialized in context");
    }
    const pcbBoard = db.pcb_board?.list()?.[0];
    const numLayers = pcbBoard?.num_layers ?? 2;
    this.ctx.numLayers = numLayers;
    kicadPcb.version = 20241229;
    const paper = new Paper2();
    paper.size = "A4";
    kicadPcb.paper = paper;
    const general = new PcbGeneral();
    general.thickness = 1.6;
    kicadPcb.general = general;
    const setup = new Setup();
    setup.padToMaskClearance = 0;
    kicadPcb.setup = setup;
    const layers = new PcbLayers();
    const layerDefinitions = [
      // Front copper layer
      new PcbLayerDefinition({ index: 0, name: "F.Cu", type: "signal" })
    ];
    for (let i = 1; i < numLayers - 1; i++) {
      layerDefinitions.push(
        new PcbLayerDefinition({ index: i, name: `In${i}.Cu`, type: "signal" })
      );
    }
    layerDefinitions.push(
      new PcbLayerDefinition({ index: 31, name: "B.Cu", type: "signal" })
    );
    layerDefinitions.push(
      new PcbLayerDefinition({ index: 32, name: "B.Adhes", type: "user" }),
      new PcbLayerDefinition({ index: 33, name: "F.Adhes", type: "user" }),
      new PcbLayerDefinition({ index: 34, name: "B.Paste", type: "user" }),
      new PcbLayerDefinition({ index: 35, name: "F.Paste", type: "user" }),
      new PcbLayerDefinition({ index: 36, name: "B.SilkS", type: "user" }),
      new PcbLayerDefinition({ index: 37, name: "F.SilkS", type: "user" }),
      new PcbLayerDefinition({ index: 38, name: "B.Mask", type: "user" }),
      new PcbLayerDefinition({ index: 39, name: "F.Mask", type: "user" }),
      // Drawing layers
      new PcbLayerDefinition({ index: 40, name: "Dwgs.User", type: "user" }),
      new PcbLayerDefinition({ index: 41, name: "Cmts.User", type: "user" }),
      new PcbLayerDefinition({ index: 42, name: "Eco1.User", type: "user" }),
      new PcbLayerDefinition({ index: 43, name: "Eco2.User", type: "user" }),
      new PcbLayerDefinition({ index: 44, name: "Edge.Cuts", type: "user" }),
      new PcbLayerDefinition({ index: 45, name: "Margin", type: "user" }),
      // Fabrication layers
      new PcbLayerDefinition({ index: 46, name: "B.CrtYd", type: "user" }),
      new PcbLayerDefinition({ index: 47, name: "F.CrtYd", type: "user" }),
      new PcbLayerDefinition({ index: 48, name: "B.Fab", type: "user" }),
      new PcbLayerDefinition({ index: 49, name: "F.Fab", type: "user" })
    );
    layers.definitions = layerDefinitions;
    kicadPcb.layers = layers;
    this.finished = true;
  }
  getOutput() {
    return this.ctx.kicadPcb;
  }
};

// lib/pcb/stages/AddNetsStage.ts
import { PcbNet } from "kicadts";
var AddNetsStage = class extends ConverterStage {
  _step() {
    const { kicadPcb } = this.ctx;
    if (!kicadPcb) {
      throw new Error("KicadPcb instance not initialized in context");
    }
    this.ctx.pcbNetMap = /* @__PURE__ */ new Map();
    const netNameByKey = /* @__PURE__ */ new Map();
    const sourceNets = this.ctx.db.source_net?.list() ?? [];
    for (const sourceNet of sourceNets) {
      const connectivityKey = sourceNet.subcircuit_connectivity_map_key || sourceNet.source_net_id;
      if (!connectivityKey) continue;
      const candidateName = sourceNet.name || sourceNet.source_net_id || "";
      const netName = candidateName && candidateName.trim().length > 0 ? candidateName : connectivityKey;
      netNameByKey.set(connectivityKey, netName);
    }
    const sourceTraces = this.ctx.db.source_trace?.list() ?? [];
    for (const sourceTrace of sourceTraces) {
      let connectivityKey = sourceTrace.subcircuit_connectivity_map_key;
      if (!connectivityKey && sourceTrace.connected_source_net_ids?.length) {
        for (const sourceNetId of sourceTrace.connected_source_net_ids) {
          const connectedNet = this.ctx.db.source_net?.get(sourceNetId);
          if (connectedNet?.subcircuit_connectivity_map_key && connectedNet.subcircuit_connectivity_map_key.length > 0) {
            connectivityKey = connectedNet.subcircuit_connectivity_map_key;
            break;
          }
        }
      }
      if (!connectivityKey) continue;
      if (!netNameByKey.has(connectivityKey)) {
        const candidateName = sourceTrace.display_name || sourceTrace.source_trace_id || "";
        const netName = candidateName && candidateName.trim().length > 0 ? candidateName : connectivityKey;
        netNameByKey.set(connectivityKey, netName);
      }
    }
    const sortedEntries = Array.from(netNameByKey.entries()).sort(
      (a, b) => a[0].localeCompare(b[0])
    );
    const nets = [];
    nets.push(new PcbNet(0, ""));
    let netNumber = 1;
    for (const [connectivityKey, netName] of sortedEntries) {
      const pcbNet = new PcbNet(netNumber, netName);
      nets.push(pcbNet);
      const netInfo = { id: netNumber, name: netName };
      this.ctx.pcbNetMap.set(connectivityKey, netInfo);
      netNumber++;
    }
    kicadPcb.nets = nets;
    this.finished = true;
  }
  getOutput() {
    return this.ctx.kicadPcb;
  }
};

// lib/pcb/stages/AddFootprintsStage.ts
import { Footprint as Footprint3, FootprintModel as FootprintModel4 } from "kicadts";

