// lib/pcb/stages/utils/CreateNpthPadFromCircuitJson.ts
import { FootprintPad as FootprintPad3, PadDrill as PadDrill2 } from "kicadts";
import { applyToPoint as applyToPoint16, rotate as rotate8, identity as identity5 } from "transformation-matrix";
function createNpthPadFromCircuitJson({
  pcbHole,
  componentCenter,
  componentRotation = 0
}) {
  if (!("x" in pcbHole && "y" in pcbHole)) {
    return null;
  }
  const relativeX = pcbHole.x - componentCenter.x;
  const relativeY = -(pcbHole.y - componentCenter.y);
  const rotationMatrix = componentRotation !== 0 ? rotate8(componentRotation * Math.PI / 180) : identity5();
  const rotatedPos = applyToPoint16(rotationMatrix, {
    x: relativeX,
    y: relativeY
  });
  let padShape = "circle";
  let padSize;
  let drill;
  let rotation = 0;
  if (pcbHole.hole_shape === "circle") {
    padShape = "circle";
    const diameter = pcbHole.hole_diameter;
    padSize = [diameter, diameter];
    drill = new PadDrill2({
      diameter
    });
  } else if (pcbHole.hole_shape === "oval" || pcbHole.hole_shape === "pill") {
    padShape = "oval";
    const width = pcbHole.hole_width;
    const height = pcbHole.hole_height;
    padSize = [width, height];
    drill = new PadDrill2({
      oval: true,
      diameter: width,
      width: height
    });
  } else if (pcbHole.hole_shape === "rotated_pill") {
    padShape = "oval";
    const width = pcbHole.hole_width;
    const height = pcbHole.hole_height;
    padSize = [width, height];
    drill = new PadDrill2({
      oval: true,
      diameter: width,
      width: height
    });
    rotation = pcbHole.ccw_rotation || 0;
  } else {
    padShape = "circle";
    const diameter = "hole_diameter" in pcbHole ? pcbHole.hole_diameter : 1;
    padSize = [diameter, diameter];
    drill = new PadDrill2({ diameter });
  }
  return new FootprintPad3({
    number: "",
    // Non-plated holes have no pad number
    padType: "np_thru_hole",
    shape: padShape,
    at: [rotatedPos.x, rotatedPos.y, rotation],
    size: padSize,
    drill,
    layers: ["*.Cu", "*.Mask"],
    removeUnusedLayers: false,
    uuid: crypto.randomUUID()
  });
}

// lib/pcb/stages/footprints-stage-converters/convertNpthHoles.ts
function convertNpthHoles(params) {
  const { pcbHoles, componentCenter, componentRotation } = params;
  const pads = [];
  for (const pcbHole of pcbHoles) {
    const pad = createNpthPadFromCircuitJson({
      pcbHole,
      componentCenter,
      componentRotation
    });
    if (pad) {
      pads.push(pad);
    }
  }
  return pads;
}

// lib/pcb/stages/AddFootprintsStage.ts
var AddFootprintsStage = class extends ConverterStage {
  componentsProcessed = 0;
  pcbComponents = [];
  includeBuiltin3dModels;
  getNetInfoForPcbPort(pcbPortId) {
    if (!pcbPortId) return void 0;
    const pcbPort = this.ctx.db.pcb_port?.get(pcbPortId);
    if (!pcbPort) return void 0;
    const sourcePortId = pcbPort.source_port_id;
    if (!sourcePortId) return void 0;
    const sourcePort = this.ctx.db.source_port?.get(sourcePortId);
    if (!sourcePort) return void 0;
    const connectivityKey = sourcePort.subcircuit_connectivity_map_key;
    if (!connectivityKey) return void 0;
    return this.ctx.pcbNetMap?.get(connectivityKey);
  }
  getCadComponentForPcbComponent(pcbComponentId) {
    const cadComponents = this.ctx.db.cad_component?.list() || [];
    return cadComponents.find(
      (cad) => cad.pcb_component_id === pcbComponentId
    );
  }
  constructor(input, ctx, options) {
    super(input, ctx);
    this.pcbComponents = this.ctx.db.pcb_component.list();
    this.includeBuiltin3dModels = options?.includeBuiltin3dModels ?? false;
  }
  _step() {
    const { kicadPcb, c2kMatPcb } = this.ctx;
    if (!kicadPcb) {
      throw new Error("KicadPcb instance not initialized in context");
    }
    if (!c2kMatPcb) {
      throw new Error("PCB transformation matrix not initialized in context");
    }
    if (this.componentsProcessed >= this.pcbComponents.length) {
      this.finished = true;
      return;
    }
    const component = this.pcbComponents[this.componentsProcessed];
    const sourceComponent = component.source_component_id ? this.ctx.db.source_component.get(component.source_component_id) : null;
    const cadComponent = this.getCadComponentForPcbComponent(
      component.pcb_component_id
    );
    const footprintName = sourceComponent ? getKicadCompatibleComponentName(
      sourceComponent,
      cadComponent
    ) : "Unknown";
    const transformedPos = applyToPoint17(c2kMatPcb, {
      x: component.center.x,
      y: component.center.y
    });
    const footprintData = `footprint:${component.pcb_component_id}:${transformedPos.x},${transformedPos.y}`;
    const footprint = new Footprint3({
      libraryLink: `tscircuit:${footprintName}`,
      layer: "F.Cu",
      at: [transformedPos.x, transformedPos.y, component.rotation || 0],
      uuid: generateDeterministicUuid(footprintData)
    });
    const fpTexts = footprint.fpTexts;
    const pcbSilkscreenTexts = this.ctx.db.pcb_silkscreen_text?.list().filter(
      (text) => text.pcb_component_id === component.pcb_component_id
    ) || [];
    fpTexts.push(
      ...convertSilkscreenTexts({
        silkscreenTexts: pcbSilkscreenTexts,
        componentCenter: component.center,
        componentRotation: component.rotation || 0,
        sourceComponentName: sourceComponent?.name
      })
    );
    const pcbNoteTexts = this.ctx.db.pcb_note_text?.list().filter(
      (text) => text.pcb_component_id === component.pcb_component_id
    ) || [];
    fpTexts.push(
      ...convertNoteTexts({
        noteTexts: pcbNoteTexts,
        componentCenter: component.center,
        componentRotation: component.rotation || 0
      })
    );
    footprint.fpTexts = fpTexts;
    const pcbSilkscreenPaths = this.ctx.db.pcb_silkscreen_path?.list().filter(
      (path) => path.pcb_component_id === component.pcb_component_id
    ) || [];
    const fpLines = footprint.fpLines ?? [];
    fpLines.push(
      ...convertSilkscreenPaths(pcbSilkscreenPaths, {
        componentCenter: component.center,
        componentRotation: component.rotation || 0
      })
    );
    footprint.fpLines = fpLines;
    const fpPads = footprint.fpPads;
    const getNetInfo = (pcbPortId) => this.getNetInfoForPcbPort(pcbPortId);
    const pcbPads = this.ctx.db.pcb_smtpad?.list().filter(
      (pad) => pad.pcb_component_id === component.pcb_component_id
    ) || [];
    const { pads: smdPads, nextPadNumber } = convertSmdPads(
      {
        pcbPads,
        componentCenter: component.center,
        componentRotation: component.rotation || 0,
        componentId: component.pcb_component_id,
        startPadNumber: 1,
        getNetInfo
      },
      this.ctx
    );
    fpPads.push(...smdPads);
    const pcbPlatedHoles = this.ctx.db.pcb_plated_hole?.list().filter(
      (hole) => hole.pcb_component_id === component.pcb_component_id
    ) || [];
    const { pads: thruHolePads } = convertPlatedHoles(
      {
        platedHoles: pcbPlatedHoles,
        componentCenter: component.center,
        componentRotation: component.rotation || 0,
        componentId: component.pcb_component_id,
        startPadNumber: nextPadNumber,
        getNetInfo
      },
      this.ctx
    );
    fpPads.push(...thruHolePads);
    const pcbHoles = this.ctx.db.pcb_hole?.list().filter(
      (hole) => hole.pcb_component_id === component.pcb_component_id
    ) || [];
    const npthPads = convertNpthHoles({
      pcbHoles,
      componentCenter: component.center,
      componentRotation: component.rotation || 0
    });
    fpPads.push(...npthPads);
    footprint.fpPads = fpPads;
    const pcbSilkscreenCircles = this.ctx.db.pcb_silkscreen_circle?.list().filter(
      (circle) => circle.pcb_component_id === component.pcb_component_id
    ) || [];
    const fpCircles = footprint.fpCircles ?? [];
    fpCircles.push(
      ...convertSilkscreenCircles(pcbSilkscreenCircles, component.center)
    );
    const pcbCourtyardCircles = this.ctx.db.pcb_courtyard_circle?.list().filter(
      (circle) => circle.pcb_component_id === component.pcb_component_id
    ) || [];
    fpCircles.push(
      ...convertCourtyardCircles(pcbCourtyardCircles, component.center)
    );
    footprint.fpCircles = fpCircles;
    const pcbFabRects = this.ctx.db.pcb_fabrication_note_rect?.list().filter(
      (rect) => rect.pcb_component_id === component.pcb_component_id
    ) || [];
    const fpRects = footprint.fpRects ?? [];
    fpRects.push(...convertFabricationNoteRects(pcbFabRects, component.center));
    const pcbNoteRects = this.ctx.db.pcb_note_rect?.list().filter(
      (rect) => rect.pcb_component_id === component.pcb_component_id
    ) || [];
    fpRects.push(...convertNoteRects(pcbNoteRects, component.center));
    const pcbCourtyardRects = this.ctx.db.pcb_courtyard_rect?.list().filter(
      (rect) => rect.pcb_component_id === component.pcb_component_id
    ) || [];
    fpRects.push(...convertCourtyardRects(pcbCourtyardRects, component.center));
    footprint.fpRects = fpRects;
    const pcbCourtyardOutlines = this.ctx.db.pcb_courtyard_outline?.list().filter(
      (outline) => outline.pcb_component_id === component.pcb_component_id
    ) || [];
    const fpPolys = convertCourtyardOutlines({
      courtyardOutlines: pcbCourtyardOutlines,
      componentCenter: component.center,
      componentRotation: component.rotation || 0
    });
    if (fpPolys.length > 0) {
      footprint.fpPolys = fpPolys;
    }
    if (cadComponent) {
      const pcbBoard = this.ctx.db.pcb_board?.list()[0];
      const boardThickness = pcbBoard?.thickness ?? 0;
      const boardLayerZOffset = component.layer === "bottom" ? -(boardThickness / 2) : boardThickness / 2;
      const models = create3DModelsFromCadComponent(
        cadComponent,
        component.center,
        {
          boardLayerZOffset,
          footprintRotation: component.rotation || 0
        }
      );
      const KICAD_3D_BASE = "${KIPRJMOD}/3dmodels";
      if (models.length > 0) {
        if (this.includeBuiltin3dModels) {
          footprint.models = models.map((model) => {
            if (!model.path) return model;
            const filename = getBasename(model.path);
            const isRemote = model.path.startsWith("http://modelcdn.tscircuit.com") || model.path.startsWith("https://modelcdn.tscircuit.com");
            const folderName = isRemote ? "tscircuit_builtin" : this.ctx.projectName ?? filename.replace(/\.[^.]+$/, "");
            const newModel = new FootprintModel4(
              `${KICAD_3D_BASE}/${folderName}.3dshapes/${filename}`
            );
            if (model.offset) newModel.offset = model.offset;
            if (model.scale) newModel.scale = model.scale;
            if (model.rotate) newModel.rotate = model.rotate;
            const sourcePath = model.path?.split("?")[0];
            if (sourcePath && !this.ctx.pcbModel3dSourcePaths?.includes(sourcePath)) {
              this.ctx.pcbModel3dSourcePaths?.push(sourcePath);
            }
            return newModel;
          });
        } else {
          footprint.models = models;
        }
      } else if (cadComponent.footprinter_string && this.includeBuiltin3dModels) {
        const { footprinter_string } = cadComponent;
        const modelPath = `${KICAD_3D_BASE}/tscircuit_builtin.3dshapes/${footprinter_string}.step`;
        footprint.models = [new FootprintModel4(modelPath)];
        const cdnUrl = `${MODEL_CDN_BASE_URL}/${footprinter_string}.step`;
        if (!this.ctx.pcbModel3dSourcePaths?.includes(cdnUrl)) {
          this.ctx.pcbModel3dSourcePaths?.push(cdnUrl);
        }
      }
    }
    const footprintMetadata = component.metadata?.kicad_footprint;
    if (sourceComponent) {
      const kicadComponentProperty = getkicadComponentProperty(sourceComponent);
      applyMetadataToFootprint({
        footprint,
        metadata: footprintMetadata,
        componentProperty: kicadComponentProperty
      });
    }
    const footprints = kicadPcb.footprints;
    footprints.push(footprint);
    kicadPcb.footprints = footprints;
    this.componentsProcessed++;
  }
  getOutput() {
    return this.ctx.kicadPcb;
  }
};

// lib/pcb/stages/AddTracesStage.ts
import { Segment, SegmentNet } from "kicadts";
import { applyToPoint as applyToPoint18 } from "transformation-matrix";
function getRoutePointLayer(point, pointRoleInSegment) {
  if ("layer" in point) {
    return point.layer;
  }
  if (point.route_type === "through_pad") {
    if (pointRoleInSegment === "start") {
      return point.end_layer;
    }
    return point.start_layer;
  }
  return void 0;
}
function getRoutePointWidth(point) {
  if ("width" in point) {
    return point.width;
  }
  return void 0;
}
var AddTracesStage = class extends ConverterStage {
  tracesProcessed = 0;
  pcbTraces = [];
  constructor(input, ctx) {
    super(input, ctx);
    this.pcbTraces = this.ctx.db.pcb_trace.list();
  }
  getRoutePointPosition(point, pointRoleInSegment) {
    if ("x" in point && "y" in point) {
      return { x: point.x, y: point.y };
    }
    if (point.route_type !== "through_pad") {
      return null;
    }
    if (pointRoleInSegment === "start") {
      return { x: point.end.x, y: point.end.y };
    }
    return { x: point.start.x, y: point.start.y };
  }
  _step() {
    const { kicadPcb, c2kMatPcb, pcbNetMap } = this.ctx;
    if (!kicadPcb) {
      throw new Error("KicadPcb instance not initialized in context");
    }
    if (!c2kMatPcb) {
      throw new Error("PCB transformation matrix not initialized in context");
    }
    if (this.tracesProcessed >= this.pcbTraces.length) {
      this.finished = true;
      return;
    }
    const trace = this.pcbTraces[this.tracesProcessed];
    const route = trace.route;
    if (!route || route.length < 2) {
      this.tracesProcessed++;
      return;
    }
    let lastKnownLayer = getRoutePointLayer(
      route[0],
      "start"
    );
    for (let i = 0; i < route.length - 1; i++) {
      const startPoint = route[i];
      const endPoint = route[i + 1];
      const startPosition = this.getRoutePointPosition(startPoint, "start");
      const endPosition = this.getRoutePointPosition(endPoint, "end");
      if (!startPosition || !endPosition) {
        throw new Error(
          `Unable to convert pcb_trace route segment ${trace.pcb_trace_id ?? this.tracesProcessed}:${i} to KiCad segment`
        );
      }
      const transformedStart = applyToPoint18(c2kMatPcb, startPosition);
      const transformedEnd = applyToPoint18(c2kMatPcb, endPosition);
      if (transformedStart.x === transformedEnd.x && transformedStart.y === transformedEnd.y) {
        continue;
      }
      let netInfo;
      if (pcbNetMap) {
        let connectivityKey = trace.subcircuit_connectivity_map_key;
        if (!connectivityKey && trace.source_trace_id) {
          const sourceTrace = this.ctx.db.source_trace?.get(
            trace.source_trace_id
          );
          if (sourceTrace) {
            connectivityKey = sourceTrace.subcircuit_connectivity_map_key;
            if (!connectivityKey && sourceTrace.connected_source_net_ids?.length) {
              for (const sourceNetId of sourceTrace.connected_source_net_ids) {
                const sourceNet = this.ctx.db.source_net?.get(sourceNetId);
                if (sourceNet?.subcircuit_connectivity_map_key) {
                  connectivityKey = sourceNet.subcircuit_connectivity_map_key;
                  break;
                }
              }
            }
          }
        }
        if (!connectivityKey && typeof trace.connection_name === "string") {
          const sourceNet = this.ctx.db.source_net?.get(trace.connection_name);
          if (sourceNet?.subcircuit_connectivity_map_key) {
            connectivityKey = sourceNet.subcircuit_connectivity_map_key;
          }
        }
        if (connectivityKey) {
          netInfo = pcbNetMap.get(connectivityKey);
        }
      }
      const segmentLayerSource = getRoutePointLayer(startPoint, "start") ?? getRoutePointLayer(endPoint, "end") ?? lastKnownLayer;
      const kicadLayer = getKicadLayer(segmentLayerSource);
      const segmentData = `segment:${transformedStart.x},${transformedStart.y}:${transformedEnd.x},${transformedEnd.y}:${kicadLayer}:${netInfo?.id ?? 0}`;
      const segment = new Segment({
        start: { x: transformedStart.x, y: transformedStart.y },
        end: { x: transformedEnd.x, y: transformedEnd.y },
        layer: kicadLayer,
        width: getRoutePointWidth(startPoint) ?? getRoutePointWidth(endPoint) ?? trace.width ?? 0.25,
        net: new SegmentNet(netInfo?.id ?? 0),
        uuid: generateDeterministicUuid(segmentData)
      });
      const segments = kicadPcb.segments;
      segments.push(segment);
      kicadPcb.segments = segments;
      const startLayer = getRoutePointLayer(startPoint, "start");
      const endLayer = getRoutePointLayer(endPoint, "end");
      if (startLayer) {
        lastKnownLayer = startLayer;
      }
      if (endLayer) {
        lastKnownLayer = endLayer;
      }
    }
    this.tracesProcessed++;
  }
  getOutput() {
    return this.ctx.kicadPcb;
  }
};

// lib/pcb/stages/AddViasStage.ts
import { Via, ViaNet } from "kicadts";
import { applyToPoint as applyToPoint19 } from "transformation-matrix";
var AddViasStage = class extends ConverterStage {
  viasProcessed = 0;
  pcbVias = [];
  constructor(input, ctx) {
    super(input, ctx);
    this.pcbVias = this.collectPcbVias();
  }
  collectPcbVias() {
    const standaloneVias = this.ctx.db.pcb_via?.list() || [];
    const seenViaKeys = new Set(
      standaloneVias.map((via) => this.getViaDedupeKey(via))
    );
    const routeDefinedVias = (this.ctx.db.pcb_trace?.list() || []).flatMap(
      (trace) => (trace.route || []).filter((point) => point.route_type === "via").map(
        (point) => ({
          x: point.x,
          y: point.y,
          outer_diameter: point.outer_diameter ?? point.via_diameter,
          hole_diameter: point.hole_diameter ?? point.via_hole_diameter,
          from_layer: point.from_layer,
          to_layer: point.to_layer,
          pcb_trace_id: trace.pcb_trace_id,
          subcircuit_connectivity_map_key: trace.subcircuit_connectivity_map_key,
          connection_name: trace.connection_name
        })
      ).filter((via) => {
        const viaKey = this.getViaDedupeKey(via);
        if (seenViaKeys.has(viaKey)) {
          return false;
        }
        seenViaKeys.add(viaKey);
        return true;
      })
    );
    return [...standaloneVias, ...routeDefinedVias];
  }
  getViaDedupeKey(via) {
    const span = [...this.getKicadViaLayers(via)].sort().join(",");
    return `${via.x}:${via.y}:${span}`;
  }
  getRawViaLayers(via) {
    if (via.layers?.length) {
      return [...via.layers];
    }
    return [via.from_layer, via.to_layer].filter(
      (layer) => Boolean(layer)
    );
  }
  getKicadViaLayers(via) {
    const rawLayers = this.getRawViaLayers(via);
    const numLayers = this.ctx.numLayers ?? 2;
    const kicadLayers = rawLayers.length > 0 ? rawLayers.map((layer) => getKicadLayer(layer)) : getViaLayers(numLayers);
    return getViaLayerSpan(kicadLayers, numLayers);
  }
  _step() {
    const { kicadPcb, c2kMatPcb, pcbNetMap } = this.ctx;
    if (!kicadPcb) {
      throw new Error("KicadPcb instance not initialized in context");
    }
    if (!c2kMatPcb) {
      throw new Error("PCB transformation matrix not initialized in context");
    }
    if (this.viasProcessed >= this.pcbVias.length) {
      this.finished = true;
      return;
    }
    const via = this.pcbVias[this.viasProcessed];
    if (!via) {
      this.finished = true;
      return;
    }
    const transformedPos = applyToPoint19(c2kMatPcb, {
      x: via.x,
      y: via.y
    });
    let netInfo;
    if (pcbNetMap) {
      let connectivityKey = via.subcircuit_connectivity_map_key;
      if (!connectivityKey && via.pcb_trace_id) {
        const pcbTrace = this.ctx.db.pcb_trace?.get(via.pcb_trace_id);
        if (pcbTrace) {
          if ("subcircuit_connectivity_map_key" in pcbTrace) {
            connectivityKey = pcbTrace.subcircuit_connectivity_map_key;
          }
          if (!connectivityKey && pcbTrace.source_trace_id) {
            const sourceTrace = this.ctx.db.source_trace?.get(
              pcbTrace.source_trace_id
            );
            if (sourceTrace) {
              if ("subcircuit_connectivity_map_key" in sourceTrace) {
                connectivityKey = sourceTrace.subcircuit_connectivity_map_key;
              }
              if (!connectivityKey && sourceTrace.connected_source_net_ids?.length) {
                for (const sourceNetId of sourceTrace.connected_source_net_ids) {
                  const sourceNet = this.ctx.db.source_net?.get(sourceNetId);
                  if (sourceNet?.subcircuit_connectivity_map_key) {
                    connectivityKey = sourceNet.subcircuit_connectivity_map_key;
                    break;
                  }
                }
              }
            }
            if (!connectivityKey) {
              const sourceNet = this.ctx.db.source_net?.get(
                pcbTrace.source_trace_id
              );
              if (sourceNet?.subcircuit_connectivity_map_key) {
                connectivityKey = sourceNet.subcircuit_connectivity_map_key;
              }
            }
          }
        }
      }
      if (!connectivityKey && via.connection_name) {
        const sourceNet = this.ctx.db.source_net?.get(via.connection_name);
        if (sourceNet?.subcircuit_connectivity_map_key) {
          connectivityKey = sourceNet.subcircuit_connectivity_map_key;
        }
      }
      if (connectivityKey) {
        netInfo = pcbNetMap.get(connectivityKey);
      }
    }
    const viaLayers = this.getKicadViaLayers(via);
    const viaSize = via.outer_diameter ?? 0.8;
    const viaDrill = via.hole_diameter ?? 0.4;
    const viaData = `via:${transformedPos.x},${transformedPos.y}:${viaSize}:${viaDrill}:${netInfo?.id ?? 0}`;
    const kicadVia = new Via({
      at: [transformedPos.x, transformedPos.y],
      size: viaSize,
      drill: viaDrill,
      layers: viaLayers,
      net: new ViaNet(netInfo?.id ?? 0),
      uuid: generateDeterministicUuid(viaData)
    });
    const vias = kicadPcb.vias;
    vias.push(kicadVia);
    kicadPcb.vias = vias;
    this.viasProcessed++;
  }
  getOutput() {
    return this.ctx.kicadPcb;
  }
};

// lib/pcb/stages/AddStandalonePcbElements.ts
import { Footprint as Footprint4 } from "kicadts";
import { applyToPoint as applyToPoint20 } from "transformation-matrix";
var AddStandalonePcbElements = class extends ConverterStage {
  unprocessedElements = [];
  constructor(input, ctx) {
    super(input, ctx);
    this.unprocessedElements = [
      ...this.ctx.db.pcb_hole.list().filter(
        (hole) => !hole.pcb_component_id
      ),
      ...this.ctx.db.pcb_plated_hole.list().filter(
        (hole) => !hole.pcb_component_id
      ),
      ...this.ctx.db.pcb_smtpad.list().filter(
        (pad) => !pad.pcb_component_id
      )
    ];
  }
  _step() {
    const { kicadPcb, c2kMatPcb } = this.ctx;
    if (!kicadPcb) {
      throw new Error("KicadPcb instance not initialized in context");
    }
    if (!c2kMatPcb) {
      throw new Error("PCB transformation matrix not initialized in context");
    }
    const elm = this.unprocessedElements.shift();
    if (!elm) {
      this.finished = true;
      return;
    }
    if (elm.type === "pcb_smtpad") {
      const pcbPad = elm;
      const padCenter = this.getPcbSmtPadCenter(pcbPad);
      const footprintSeed = `standalone_smtpad:${pcbPad.pcb_smtpad_id}:${padCenter.x},${padCenter.y}`;
      const kicadPos = applyToPoint20(c2kMatPcb, padCenter);
      const footprint = new Footprint4({
        libraryLink: this.getSmtPadLibraryLink(pcbPad),
        layer: "F.Cu",
        at: [kicadPos.x, kicadPos.y, 0],
        uuid: generateDeterministicUuid(footprintSeed)
      });
      footprint.fpPads = [
        createSmdPadFromCircuitJson({
          pcbPad,
          componentCenter: padCenter,
          padNumber: 1,
          componentRotation: 0,
          componentId: pcbPad.pcb_smtpad_id
        })
      ];
      const footprints = kicadPcb.footprints;
      footprints.push(footprint);
      kicadPcb.footprints = footprints;
    } else if (elm.type === "pcb_hole") {
      const hole = elm;
      const footprintSeed = `standalone_hole:${hole.pcb_hole_id}:${hole.x},${hole.y}`;
      const kicadPos = applyToPoint20(c2kMatPcb, { x: hole.x, y: hole.y });
      const libraryLink = this.getHoleLibraryLink(hole);
      const footprint = new Footprint4({
        libraryLink,
        layer: "F.Cu",
        at: [kicadPos.x, kicadPos.y, 0],
        uuid: generateDeterministicUuid(footprintSeed)
      });
      const ccwRotationDegrees = 0;
      const npthPads = convertNpthHoles({
        pcbHoles: [hole],
        componentCenter: { x: hole.x, y: hole.y },
        // Use hole center for negative offset
        componentRotation: ccwRotationDegrees
      });
      if (npthPads.length > 0) {
        footprint.fpPads = npthPads;
        const footprints = kicadPcb.footprints;
        footprints.push(footprint);
        kicadPcb.footprints = footprints;
      }
    } else if (elm.type === "pcb_plated_hole") {
      const hole = elm;
      const footprintSeed = `standalone_plated_hole:${hole.pcb_plated_hole_id}:${hole.x},${hole.y}`;
      const kicadPos = applyToPoint20(c2kMatPcb, { x: hole.x, y: hole.y });
      const libraryLink = this.getPlatedHoleLibraryLink(hole);
      const footprint = new Footprint4({
        libraryLink,
        layer: "F.Cu",
        at: [kicadPos.x, kicadPos.y, 0],
        uuid: generateDeterministicUuid(footprintSeed)
      });
      const pad = createThruHolePadFromCircuitJson({
        platedHole: hole,
        componentCenter: { x: hole.x, y: hole.y },
        padNumber: 1,
        componentRotation: 0
      });
      if (pad) {
        footprint.fpPads = [pad];
        const footprints = kicadPcb.footprints;
        footprints.push(footprint);
        kicadPcb.footprints = footprints;
      }
    }
  }
  getHoleLibraryLink(hole) {
    const { hole_shape: shape } = hole;
    if (shape === "circle") {
      return `tscircuit:hole_${shape}_holeDiameter${hole.hole_diameter}mm`;
    }
    if (shape === "pill" || shape === "oval") {
      const h = hole;
      return `tscircuit:hole_${shape}_holeWidth${h.hole_width}mm_holeHeight${h.hole_height}mm`;
    }
    if (shape === "rotated_pill") {
      return `tscircuit:hole_${shape}_holeWidth${hole.hole_width}mm_holeHeight${hole.hole_height}mm_ccwRotation${hole.ccw_rotation}deg`;
    }
    return "tscircuit:hole";
  }
  getPlatedHoleLibraryLink(hole) {
    const shape = hole.shape;
    if (shape === "circle") {
      return `tscircuit:platedhole_${shape}_holeDiameter${hole.hole_diameter}mm_outerDiameter${hole.outer_diameter}mm`;
    }
    if (shape === "pill" || shape === "oval") {
      const h = hole;
      return `tscircuit:platedhole_${shape}_holeWidth${h.hole_width}mm_holeHeight${h.hole_height}mm_outerWidth${h.outer_width}mm_outerHeight${h.outer_height}mm`;
    }
    if (shape === "pill_hole_with_rect_pad") {
      const h = hole;
      return `tscircuit:platedhole_${shape}_holeWidth${h.hole_width}mm_holeHeight${h.hole_height}mm_rectPadWidth${h.rect_pad_width}mm_rectPadHeight${h.rect_pad_height}mm`;
    }
    if (shape === "circular_hole_with_rect_pad") {
      const h = hole;
      let link = `tscircuit:platedhole_${shape}_holeDiameter${h.hole_diameter}mm_rectPadWidth${h.rect_pad_width}mm_rectPadHeight${h.rect_pad_height}mm`;
      if (h.rect_ccw_rotation) {
        link += `_ccwRotation${h.rect_ccw_rotation}deg`;
      }
      return link;
    }
    if (shape === "rotated_pill_hole_with_rect_pad") {
      const h = hole;
      let link = `tscircuit:platedhole_${shape}_holeWidth${h.hole_width}mm_holeHeight${h.hole_height}mm_rectPadWidth${h.rect_pad_width}mm_rectPadHeight${h.rect_pad_height}mm`;
      if (h.rect_ccw_rotation) {
        link += `_ccwRotation${h.rect_ccw_rotation}deg`;
      }
      return link;
    }
    return "tscircuit:platedhole";
  }
  getPcbSmtPadCenter(pcbPad) {
    if ("x" in pcbPad && "y" in pcbPad) {
      return { x: pcbPad.x, y: pcbPad.y };
    }
    const points = pcbPad.points;
    return {
      x: points.reduce((sum, point) => sum + point.x, 0) / points.length,
      y: points.reduce((sum, point) => sum + point.y, 0) / points.length
    };
  }
  getSmtPadLibraryLink(pcbPad) {
    if (pcbPad.shape === "circle" && "radius" in pcbPad) {
      return `tscircuit:smtpad_circle_diameter${pcbPad.radius * 2}mm`;
    }
    if ((pcbPad.shape === "rect" || pcbPad.shape === "rotated_rect") && "width" in pcbPad && "height" in pcbPad) {
      return `tscircuit:smtpad_${pcbPad.shape}_width${pcbPad.width}mm_height${pcbPad.height}mm`;
    }
    return "tscircuit:smtpad";
  }
  getOutput() {
    return this.ctx.kicadPcb;
  }
};

