    for (const prop of properties) {
      if (prop.key === "Footprint" && prop.value) {
        const parts = prop.value.split(":");
        if (parts.length > 1) {
          prop.value = `${fpLibraryName}:${parts[1]}`;
        } else if (prop.value.trim()) {
          prop.value = `${fpLibraryName}:${prop.value}`;
        }
      }
    }
